using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace PlayStories
{
    /// <summary>Small helpers to build uGUI hierarchies from code.</summary>
    public static class UI
    {
        static TMP_FontAsset s_Font;
        static Material s_Outlined, s_OutlinedThin, s_Plain;

        /// <summary>Picks up the SDF font + material presets generated by the editor builder.</summary>
        public static void Init(UISkin skin)
        {
            s_Font = skin.fontAsset;
            s_Plain = skin.fontAsset != null ? skin.fontAsset.material : null;
            s_Outlined = skin.textOutlined != null ? skin.textOutlined : s_Plain;
            s_OutlinedThin = skin.textOutlinedThin != null ? skin.textOutlinedThin : s_Outlined;
        }

        public enum TextStyle { Plain, Outlined, OutlinedThin }

        public static RectTransform Rect(Transform parent, string name)
        {
            var go = new GameObject(name, typeof(RectTransform));
            go.layer = parent != null ? parent.gameObject.layer : 5;
            var rt = (RectTransform)go.transform;
            rt.SetParent(parent, false);
            return rt;
        }

        public static void Stretch(RectTransform rt, float inset = 0f)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.offsetMin = new Vector2(inset, inset);
            rt.offsetMax = new Vector2(-inset, -inset);
        }

        public static void Anchor(RectTransform rt, Vector2 anchor, Vector2 pivot, Vector2 pos, Vector2 size)
        {
            rt.anchorMin = rt.anchorMax = anchor;
            rt.pivot = pivot;
            rt.anchoredPosition = pos;
            rt.sizeDelta = size;
        }

        public static Image Image(Transform parent, string name, Sprite sprite, Color? color = null)
        {
            var rt = Rect(parent, name);
            var img = rt.gameObject.AddComponent<Image>();
            img.sprite = sprite;
            img.color = color ?? Color.white;
            if (sprite != null && sprite.border != Vector4.zero) img.type = UnityEngine.UI.Image.Type.Sliced;
            return img;
        }

        public static TextMeshProUGUI Text(Transform parent, string name, string text, float size,
            TextStyle style = TextStyle.Outlined, Color? color = null, TextAlignmentOptions align = TextAlignmentOptions.Center)
        {
            var rt = Rect(parent, name);
            var t = rt.gameObject.AddComponent<TextMeshProUGUI>();
            t.font = s_Font;
            t.fontSharedMaterial = style == TextStyle.Outlined ? s_Outlined : style == TextStyle.OutlinedThin ? s_OutlinedThin : s_Plain;
            t.text = text;
            t.fontSize = size;
            t.color = color ?? Color.white;
            t.alignment = align;
            t.textWrappingMode = TextWrappingModes.NoWrap;
            t.overflowMode = TextOverflowModes.Overflow;
            t.raycastTarget = false;
            return t;
        }

        /// <summary>Full-screen background that always covers its parent (crops instead of letterboxing).</summary>
        public static Image CoverImage(Transform parent, string name, Sprite sprite)
        {
            var holder = Rect(parent, name);
            Stretch(holder);
            var mask = holder.gameObject.AddComponent<RectMask2D>();
            mask.enabled = false; // parent is full screen anyway; enable if used inside a card
            var img = Image(holder, "Image", sprite);
            img.raycastTarget = false;
            var fit = img.gameObject.AddComponent<AspectRatioFitter>();
            fit.aspectMode = AspectRatioFitter.AspectMode.EnvelopeParent;
            fit.aspectRatio = sprite != null ? sprite.rect.width / sprite.rect.height : 1.4f;
            return img;
        }

        public static CanvasGroup Group(Component c)
        {
            var g = c.GetComponent<CanvasGroup>();
            return g != null ? g : c.gameObject.AddComponent<CanvasGroup>();
        }
    }
}
